<?php
namespace Database\Seeders;
use App\Models\Appointment;use App\Models\Doctor;use App\Models\MedicalRecord;use App\Models\Pasien;use Illuminate\Database\Seeder;
class ClinicDemoSeeder extends Seeder {public function run():void{$docs=[];foreach([['dr. Nadia Putri','Dokter Umum','R-01'],['dr. Bima Pratama','Penyakit Dalam','R-02'],['dr. Sinta Maharani','Kesehatan Anak','R-03'],['dr. Arif Wibowo','Kesehatan Gigi','R-04']] as [$n,$s,$r])$docs[]=Doctor::firstOrCreate(['name'=>$n],['specialty'=>$s,'room'=>$r,'is_active'=>true]);$rows=[['Andi Saputra','081234560101','Jl. Melati No. 12','Laki-laki','1994-03-12','O'],['Nadia Lestari','081234560102','Jl. Kenanga No. 8','Perempuan','1998-08-20','A'],['Rizky Ramadhan','081234560103','Jl. Mawar No. 4','Laki-laki','1989-11-02','B'],['Dewi Anggraini','081234560104','Jl. Anggrek No. 6','Perempuan','2001-01-25','AB'],['Fajar Hidayat','081234560105','Jl. Cendana No. 2','Laki-laki','1978-07-09','O'],['Maya Puspita','081234560106','Jl. Flamboyan No. 9','Perempuan','1992-05-17','A']];$ps=[];foreach($rows as $i=>$r)$ps[]=Pasien::firstOrCreate(['No_Hp'=>$r[1]],['Nama_Pasien'=>$r[0],'Alamat_Pasien'=>$r[2],'jenis_kelamin'=>$r[3],'tanggal_lahir'=>$r[4],'golongan_darah'=>$r[5],'kode_pasien'=>'CD-'.str_pad((string)($i+1),5,'0',STR_PAD_LEFT)]);$slots=[[-2,'Selesai'],[-1,'Selesai'],[0,'Menunggu'],[1,'Menunggu'],[2,'Diperiksa'],[3,'Menunggu'],[4,'Menunggu'],[25,'Menunggu']];foreach($slots as $i=>[$off,$status]){$dt=now()->addDays($off)->setTime(9+($i%5),($i%2)*30);$a=Appointment::firstOrCreate(['pasien_id'=>$ps[$i%count($ps)]->id,'scheduled_at'=>$dt],['doctor_id'=>$docs[$i%count($docs)]->id,'service_name'=>['Konsultasi umum','Pemeriksaan rutin','Konsultasi anak','Pemeriksaan gigi'][$i%4],'status'=>$status,'reason'=>'Pemeriksaan dan konsultasi.']);if($status==='Selesai')MedicalRecord::firstOrCreate(['appointment_id'=>$a->id],['pasien_id'=>$a->pasien_id,'doctor_id'=>$a->doctor_id,'visited_at'=>$dt,'complaint'=>'Keluhan ringan untuk contoh data.','diagnosis'=>'Catatan demonstrasi — bukan diagnosis medis.','treatment'=>'Edukasi dan pemantauan.','prescription'=>'Tidak ada resep pada data demo.']);}}}
